    if (m) { cb(m); return; }
    var iv = setInterval(function () {
        var m2 = Process.findModuleByName(name);
        if (m2) { clearInterval(iv); cb(m2); }
    }, 50);
}

waitForModule(SO_NAME, function (mod) {
    log("模块已加载: " + mod.name + " base=" + mod.base + " size=" + mod.size);
    log("符号表:");
    mod.enumerateSymbols().forEach(function (sym) {
        log("  " + sym.address + "  " + sym.name + (sym.isGlobal ? " [G]" : ""));
    });

    // 2) 枚举 JNI 导出函数（Java_xxx_yyy 格式）
    var exports = mod.enumerateExports();
    exports.forEach(function (e) {
