**通用 Frida 脚本骨架（DexFile::OpenMemory / OpenCommon 定位）：**

```javascript
// frida -U -f [包名] -l dump_dex.js --no-pause
function hookDexFile() {
    var libart = Process.findModuleByName("libart.so");
    if (!libart) { console.log("[-] libart not found"); return; }

    // 1) DexFile::OpenMemory(const uint8_t*, size_t, const std::string&, const std::string&, std::string*)
    var openMemorySym = null;
    libart.enumerateSymbols().forEach(function (s) {
        if (s.name.indexOf("DexFile") !== -1 &&
            s.name.indexOf("OpenMemory") !== -1) {
            console.log("[+] sym: " + s.name + " @ " + s.address);
            openMemorySym = s.address;
        }
    });

    if (openMemorySym) {
        Interceptor.attach(openMemorySym, {
            onEnter: function (args) {
                // 按实际符号签名可能偏移不同，先打印前几个参数
                var base = args[0];
                var size = args[1].toInt32();
                if (size > 0x100 && size < 0x10000000) {
                    console.log("[+] OpenMemory base=" + base + " size=0x" + size.toString(16));
                    dumpToFile(base, size);
                }
            }
        });
    }

    // 2) DexFile::OpenCommon 兜底
    libart.enumerateSymbols().forEach(function (s) {
        if (s.name.indexOf("DexFile") !== -1 && s.name.indexOf("OpenCommon") !== -1) {
            console.log("[+] OpenCommon sym: " + s.name + " @ " + s.address);
            Interceptor.attach(s.address, {
                onEnter: function (args) {
                    try {
                        var base = args[0];
                        var size = args[1].toInt32();
                        if (size > 0x100 && size < 0x10000000) {
                            console.log("[+] OpenCommon base=" + base + " size=0x" + size.toString(16));
                            dumpToFile(base, size);
                        }
                    } catch (e) { }
                }
            });
        }
    });
}

function dumpToFile(base, size) {
    var data = Memory.readByteArray(base, size);
    var name = "/data/local/tmp/dex_" + Date.now() + "_0x" + size.toString(16) + ".dex";
    var f = new File(name, "wb");
    f.write(data);
    f.flush();
    f.close();
    console.log("[+] dumped: " + name);
}

setImmediate(hookDexFile);
```

