```c
// EacDrv.c —— 只做 MmCopyVirtualMemory 读写 + 进程/模块枚举
#include <ntifs.h>
#include <ntddk.h>

#define EACDRV_DEV  L"\\Device\\EacDrv"
#define EACDRV_SYM  L"\\DosDevices\\EacDrv"
#define IOCTL_READ   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_BASE   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x803, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQ {
    ULONG  Pid;
    PVOID  Addr;
    PVOID  Buf;
    SIZE_T Size;
    SIZE_T Done;
    NTSTATUS Status;
} RW_REQ, *PRW_REQ;

static NTSTATUS CopyMem(ULONG pid, PVOID addr, PVOID buf, SIZE_T size, BOOLEAN write) {
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &proc);
    if (!NT_SUCCESS(st)) return st;
    SIZE_T done = 0;
    if (write) st = MmCopyVirtualMemory(PsGetCurrentProcess(), buf, proc, addr, size, KernelMode, &done);
    else       st = MmCopyVirtualMemory(proc, addr, PsGetCurrentProcess(), buf, size, KernelMode, &done);
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS DrvDispatch(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG code = sp->Parameters.DeviceIoControl.IoControlCode;
    PVOID buf = irp->AssociatedIrp.SystemBuffer;

    if (code == IOCTL_READ || code == IOCTL_WRITE) {
        PRW_REQ r = (PRW_REQ)buf;
        // 简化：buf 里前 sizeof(RW_REQ) 是头，后面跟数据；生产上分两次 IOCTL
        st = CopyMem(r->Pid, r->Addr, (PUCHAR)buf + sizeof(RW_REQ), r->Size, code == IOCTL_WRITE);
        r->Status = st;
        irp->IoStatus.Information = sizeof(RW_REQ) + (code == IOCTL_READ ? r->Size : 0);
    } else if (code == IOCTL_BASE) {
        // 输出 [pid, base]，真实实现遍历 PEB/Ldr；此处占位
        st = STATUS_NOT_IMPLEMENTED;
        irp->IoStatus.Information = 0;
    }
    irp->IoStatus.Status = st;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

static VOID DrvUnload(PDRIVER_OBJECT drv) {
    UNICODE_STRING sym; RtlInitUnicodeString(&sym, EACDRV_SYM);
    IoDeleteSymbolicLink(&sym);
    if (drv->DeviceObject) IoDeleteDevice(drv->DeviceObject);
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg) {
    UNREFERENCED_PARAMETER(reg);
    UNICODE_STRING name, sym;
    PDEVICE_OBJECT dev = NULL;
    RtlInitUnicodeString(&name, EACDRV_DEV);
    RtlInitUnicodeString(&sym, EACDRV_SYM);
