int main(void) {
    PPEB peb = (PPEB)__readgsqword(0x60);
    PPEB_LDR_DATA_FULL ldr = (PPEB_LDR_DATA_FULL)peb->Ldr;
    PLIST_ENTRY head = &ldr->InLoadOrderModuleList;
    PLIST_ENTRY cur  = head->Flink;

    printf("[probe] user-mode Ldr list (InLoadOrder):\n");
    while (cur != head) {
        PLDR_DATA_TABLE_ENTRY_FULL e =
            CONTAINING_RECORD(cur, LDR_DATA_TABLE_ENTRY_FULL, InLoadOrderLinks);
        if (e->BaseDllName.Buffer && e->BaseDllName.Length) {
            printf("  base=%p size=0x%lx  %.*ws\n",
                   e->DllBase, (unsigned long)e->SizeOfImage,
                   e->BaseDllName.Length / sizeof(WCHAR), e->BaseDllName.Buffer);
        }
        cur = cur->Flink;
    }

    // 内核侧：判断驱动是否还在 PsLoadedModuleList 里（用 NtQuerySystemInformation 拉 SystemModuleInformation）
    HMODULE ntdll = GetModuleHandleW(L"ntdll.dll");
    typedef NTSTATUS (NTAPI *pNtQSI)(ULONG, PVOID, ULONG, PULONG);
    pNtQSI NtQSI = (pNtQSI)GetProcAddress(ntdll, "NtQuerySystemInformation");

    ULONG need = 0;
    NtQSI(11 /*SystemModuleInformation*/, NULL, 0, &need); // 11 = SystemModuleInformation
    PBYTE buf = (PBYTE)VirtualAlloc(NULL, need, MEM_COMMIT, PAGE_READWRITE);
    if (NtQSI(11, buf, need, &need) == 0) {
