// 暴力特征扫描：金币通常是较小 int32，先按"已知当前值"收束
function scanInt32(target) {
    var ranges = Process.enumerateRanges('rw-');
    var hits = [];
    ranges.forEach(function (r) {
        if (r.size > 64 * 1024 * 1024) return;
        var buf = Memory.readByteArray(r.base, Math.min(r.size, 64 * 1024 * 1024));
        var view = new DataView(buf);
        for (var i = 0; i + 4 <= view.byteLength; i += 4) {
            if (view.getInt32(i, true) === target) {
                hits.push(r.base.add(i));
            }
        }
    });
    return hits;
}

