// 1) 句柄被剥权限时的保活：打开前先降请求权限，失败再走 Nt 直调
#include <windows.h>
#include <winternl.h>
#pragma comment(lib, "ntdll.lib")

typedef NTSTATUS(NTAPI* pNtOpenProcess)(PHANDLE, ACCESS_MASK, POBJECT_ATTRIBUTES, PCLIENT_ID);

HANDLE OpenTargetStealth(DWORD pid) {
    HANDLE h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
    if (h) return h;
    // ObRegisterCallbacks 剥了 VM_READ 时，用 Nt 直调 + 最小权限再试
    static pNtOpenProcess NtOpenProcess =
        (pNtOpenProcess)GetProcAddress(GetModuleHandleW(L"ntdll.dll"), "NtOpenProcess");
    OBJECT_ATTRIBUTES oa = { sizeof(oa) };
    CLIENT_ID cid = { (HANDLE)(ULONG_PTR)pid, nullptr };
    HANDLE h2 = nullptr;
    NTSTATUS st = NtOpenProcess(&h2, PROCESS_QUERY_LIMITED_INFORMATION, &oa, &cid);
    return NT_SUCCESS(st) ? h2 : nullptr;
}
```

