// esp_probe.cpp — 外部读取骨架，先验证"能不能读、读到了什么"
// cl /std:c++17 /O2 esp_probe.cpp /link user32.lib
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap); return 0;
}

// 模块基址：exe 的基址就是从 PE 里读；dll 走快照
uintptr_t ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { uintptr_t b = (uintptr_t)me.modBaseAddr; CloseHandle(snap); return b; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap); return 0;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"[模块名].dll";
    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"process not found: %s\n", proc); return 1; }
    uintptr_t base = ModuleBase(pid, mod);
    wprintf(L"pid=%lu module=%s base=0x%llX\n", pid, mod, (unsigned long long)base);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 1; }

    // 多级指针链遍历：base -> +[偏移1] -> +[偏移2] -> ...
    std::vector<uintptr_t> chain = { 0x[偏移1], 0x[偏移2], 0x[偏移3] };
    uintptr_t addr = base;
    for (size_t i = 0; i < chain.size(); ++i) {
        uintptr_t next = 0;
        if (!ReadProcessMemory(h, (LPCVOID)(addr + chain[i]), &next, sizeof(next), nullptr)) {
            wprintf(L"read fail at level %zu addr=0x%llX err=%lu\n", i, (unsigned long long)(addr + chain[i]), GetLastError());
            CloseHandle(h); return 1;
        }
        addr = next;
        wprintf(L"level %zu -> 0x%llX\n", i, (unsigned long long)addr);
    }
    // 结构体落点：从这里往下按字段偏移读
    CloseHandle(h);
    return 0;
}
