## 驱动工程（WDM，读写 + 进程隐藏句柄）

`Driver.c`：

```c
#include <ntifs.h>
#include <ntddk.h>

#define DEVICE_NAME L"\\Device\\MyRwDrv"
#define SYM_NAME    L"\\DosDevices\\MyRwDrv"

typedef struct _RW_REQ {
    ULONG  Pid;
    ULONG64 Address;
    ULONG64 Buffer;     // 用户态缓冲
    SIZE_T  Size;
    ULONG   Write;      // 0=读 1=写
    SIZE_T  Done;
} RW_REQ, *PRW_REQ;

#define IOCTL_RW CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)

// MmCopyVirtualMemory 双向拷贝
static NTSTATUS DoCopy(ULONG Pid, ULONG64 Src, ULONG64 Dst, SIZE_T Size, BOOLEAN ToDst)
{
    PEPROCESS proc = NULL;
    NTSTATUS  st   = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)Pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    KAPC_STATE apc;
    KeStackAttachProcess(proc, &apc);

    SIZE_T done = 0;
    st = (ToDst
        ? MmCopyVirtualMemory(PsGetCurrentProcess(), (PVOID)Dst,
                              proc, (PVOID)Src, Size, KernelMode, &done)
        : MmCopyVirtualMemory(proc, (PVOID)Src,
                              PsGetCurrentProcess(), (PVOID)Dst, Size, KernelMode, &done));

    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(proc);
    return st;
}
```

关键点：`MmCopyVirtualMemory` 走的是内核态拷贝，不经过用户态 `ReadProcessMemory`，句柄表里看不到你开目标进程。`KeStackAttachProcess` 让 `Src` 直接按目标进程虚拟地址解释，不用自己切 CR3。

IOCTL 分发：

```c
static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION isl = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_PARAMETER;

    if (isl->Parameters.DeviceIoControl.IoControlCode == IOCTL_RW) {
        PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;
        if (req && req->Size) {
            if (!req->Write)
                st = DoCopy(req->Pid, req->Address, req->Buffer, req->Size, FALSE);
            else
                st = DoCopy(req->Pid, req->Address, req->Buffer, req->Size, TRUE);
            req->Done = NT_SUCCESS(st) ? req->Size : 0;
            irp->IoStatus.Information = sizeof(RW_REQ);
        }
    }
    irp->IoStatus.Status = st;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    UNREFERENCED_PARAMETER(reg);
    UNICODE_STRING dn, sn;
    PDEVICE_OBJECT dev;

    RtlInitUnicodeString(&dn, DEVICE_NAME);
    RtlInitUnicodeString(&sn, SYM_NAME);

    NTSTATUS st = IoCreateDevice(drv, 0, &dn, FILE_DEVICE_UNKNOWN,
                                 FILE_DEVICE_SECURE_OPEN, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;

    st = IoCreateSymbolicLink(&sn, &dn);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }

    drv->MajorFunction[IRP_MJ_CREATE] = Dispatch;
    drv->MajorFunction[IRP_MJ_CLOSE]  = Dispatch;
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Dispatch;
    return STATUS_SUCCESS;
}
```

`DrvUnload` 里补：`IoDeleteSymbolicLink` + `IoDeleteDevice`，留卸载入口。

