struct Matrix4x4 { float m[4][4]; };

// 列主序（D3D 常用）：v' = M * v
static inline bool WorldToScreen(const float world[3], float out[2],
                                 const Matrix4x4& vm, int sw, int sh)
{
    float x = world[0]*vm.m[0][0] + world[1]*vm.m[1][0] + world[2]*vm.m[2][0] + vm.m[3][0];
    float y = world[0]*vm.m[0][1] + world[1]*vm.m[1][1] + world[2]*vm.m[2][1] + vm.m[3][1];
    float w = world[0]*vm.m[0][3] + world[1]*vm.m[1][3] + world[2]*vm.m[2][3] + vm.m[3][3];
    if (w < 0.001f) return false;              // 背后剔除
    float invW = 1.0f / w;
    x *= invW; y *= invW;
    out[0] = (x * 0.5f + 0.5f) * (float)sw;
    out[1] = (1.0f - (y * 0.5f + 0.5f)) * (float)sh;   // 屏幕 Y 翻转
    return true;
}

