## 1. 驱动入口 / 设备与 IOCTL 骨架

```c
// cr3rw.h
#pragma once
#include <ntifs.h>

#define CR3_DEVICE_NAME   L"\\Device\\Cr3Rw"
#define CR3_SYMLINK_NAME  L"\\DosDevices\\Cr3Rw"

#define IOCTL_CR3_READ_VIRT   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_CR3_WRITE_VIRT  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_CR3_GET_BASE    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x803, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_CR3_GET_CR3     CTL_CODE(FILE_DEVICE_UNKNOWN, 0x804, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _CR3_REQ {
    ULONG  Pid;
    ULONGLONG Address;      // 目标进程虚拟地址
    ULONGLONG Buffer;       // 用户态缓冲
    ULONG  Size;
    ULONGLONG Result;       // 返回：实际读写的物理地址 / Base
