```c
// cr3rw.c
#include "cr3rw.h"

NTSTATUS DriverEntry(PDRIVER_OBJECT Driver, PUNICODE_STRING RegistryPath);
VOID     Cr3Unload(PDRIVER_OBJECT Driver);
NTSTATUS Cr3CreateClose(PDEVICE_OBJECT Dev, PIRP Irp);
NTSTATUS Cr3DeviceControl(PDEVICE_OBJECT Dev, PIRP Irp);

NTSTATUS DriverEntry(PDRIVER_OBJECT Driver, PUNICODE_STRING RegistryPath)
{
    UNREFERENCED_PARAMETER(RegistryPath);
    PDEVICE_OBJECT dev = NULL;
    UNICODE_STRING devName, symName;
    NTSTATUS st;

    RtlInitUnicodeString(&devName, CR3_DEVICE_NAME);
    RtlInitUnicodeString(&symName, CR3_SYMLINK_NAME);

    st = IoCreateDevice(Driver, 0, &devName, FILE_DEVICE_UNKNOWN,
                        FILE_DEVICE_SECURE_OPEN, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;

    st = IoCreateSymbolicLink(&symName, &devName);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }

    Driver->MajorFunction[IRP_MJ_CREATE]         = Cr3CreateClose;
    Driver->MajorFunction[IRP_MJ_CLOSE]          = Cr3CreateClose;
    Driver->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Cr3DeviceControl;
    Driver->DriverUnload                        = Cr3Unload;

    dev->Flags |= DO_BUFFERED_IO;
    dev->Flags &= ~DO_DEVICE_INITIALIZING;
    return STATUS_SUCCESS;
}

VOID Cr3Unload(PDRIVER_OBJECT Driver)
{
    UNICODE_STRING symName;
    RtlInitUnicodeString(&symName, CR3_SYMLINK_NAME);
    IoDeleteSymbolicLink(&symName);
    if (Driver->DeviceObject) IoDeleteDevice(Driver->DeviceObject);
}
```

