**串口参数**：`115200 8N1`，无流控。kmbox NET 走 UDP（端口 `8888` 上发命令、`8889` 收回调），kmbox B/B+ 走 USB CDC 串口（`COMx` / `/dev/ttyACM0`）。

## 1. 基础命令（ASCII，回车换行 `\r\n` 结尾）

```
# 鼠标相对移动
km.move(10,0)              // 右移 10
km.move(-5,-3)             // 左 5 上 3
km.move(10,0,20)           // 第三个参数=每步耗时(ms)，做平滑
km.move_bezier(x,y,segs,cx1,cy1,cx2,cy2)   // 贝塞尔曲线移动，拟人化用这个
km.wheel(120)              // 滚轮
km.left(1)  km.left(0)     // 左键按下/抬起
km.right(1) km.right(0)
km.middle(1) km.middle(0)
km.key(4,1) km.key(4,0)    // 键盘：4=A，参数1=按下 0=抬起
km.key_stop()              // 全部按键抬起
km.ifdown(0,1)             // 判断按键是否按下：0=左键 返回1/0
km.ifdown(0,0)             // 第二个参数=清空缓存
km.monitor(port)           // 开启硬件键鼠回调上报
```

其中 `km.move_bezier` 的完整签名是：

```
km.move_bezier(x, y, segments, cx1, cy1, cx2, cy2)
```

其中 `(cx1,cy1)`、`(cx2,cy2)` 是相对起点的两个控制点偏移。实战自瞄的写法是每帧算一个目标点，控制点随机抖动 ±15%，段数 8~25 随机，这样轨迹看起来更自然不会呈直线。

## 2. C 实现：串口打开 + 发指令

```c
// kmbox_serial.c  —— Linux / Windows 通用思路，打开后按行写
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#ifdef _WIN32
#include <windows.h>
static HANDLE hPort;
int km_open(const char* port){
    char path[64]; sprintf(path, "\\\\.\\%s", port);   // COM3 -> \\.\COM3
    hPort = CreateFileA(path, GENERIC_READ|GENERIC_WRITE, 0, NULL,
                        OPEN_EXISTING, 0, NULL);
    if (hPort == INVALID_HANDLE_VALUE) return -1;
    DCB dcb = {0}; dcb.DCBlength = sizeof(DCB);
    GetCommState(hPort, &dcb);
    dcb.BaudRate = 115200; dcb.ByteSize = 8; dcb.Parity = NOPARITY;
    dcb.StopBits = ONESTOPBIT; dcb.fBinary = TRUE;
    dcb.fDtrControl = DTR_CONTROL_DISABLE;
    dcb.fRtsControl = RTS_CONTROL_DISABLE;
    SetCommState(hPort, &dcb);
    COMMTIMEOUTS to = {0};
    to.ReadIntervalTimeout = 1; to.ReadTotalTimeoutConstant = 5;
    SetCommTimeouts(hPort, &to);
    return 0;
}
int km_write(const char* cmd){
    char buf[256]; int n = sprintf(buf, "%s\r\n", cmd);
    DWORD w; return WriteFile(hPort, buf, n, &w, NULL) ? 0 : -1;
}
#else
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
static int fd = -1;
int km_open(const char* dev){          // "/dev/ttyACM0"
    fd = open(dev, O_RDWR | O_NOCTTY);
    if (fd < 0) return -1;
    struct termios tio; tcgetattr(fd, &tio);
    cfmakeraw(&tio);
    cfsetispeed(&tio, B115200); cfsetospeed(&tio, B115200);
    tio.c_cflag |= (CLOCAL | CREAD); tio.c_cflag &= ~CRTSCTS;
    tio.c_cc[VMIN] = 0; tio.c_cc[VTIME] = 1;
    tcsetattr(fd, TCSANOW, &tio);
    return 0;
}
int km_write(const char* cmd){
    char buf[256]; int n = snprintf(buf, sizeof buf, "%s\r\n", cmd);
    return (write(fd, buf, n) == n) ? 0 : -1;
}
#endif
```

