// base_scan.cpp — cl /std:c++17 /EHsc base_scan.cpp /link Psapi.lib
#include <windows.h>
#include <psapi.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* procName = argc > 1 ? argv[1] : L"[进程名]";
    DWORD pid = FindPid(procName);
    if (!pid) { wprintf(L"pid not found\n"); return 1; }
    wprintf(L"pid = %lu\n", pid);

    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 1; }

    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        for (DWORD i = 0; i < need / sizeof(HMODULE); ++i) {
            wchar_t path[MAX_PATH]{};
            GetModuleFileNameExW(h, mods[i], path, MAX_PATH);
            wprintf(L"%-64s base=%p\n", path, mods[i]);
        }
    }
    CloseHandle(h);
    return 0;
}
