    if (!h) { printf("OpenProcess failed: %lu\n", GetLastError()); return 2; }

    HANDLE ms = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me = { sizeof(me) };
    for (BOOL ok = Module32FirstW(ms, &me); ok; ok = Module32NextW(ms, &me)) {
        if (!mod[0] || !_wcsicmp(me.szModule, mod))
            wprintf(L"%-32s base=0x%p size=0x%08X\n", me.szModule, me.modBaseAddr, me.modBaseSize);
