```c
uintptr_t rpm64(HANDLE h, uintptr_t addr) {
    uintptr_t v = 0; SIZE_T n = 0;
    ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(v), &n);
    return v;
}
// ptr_chain(h, base + 0x[一级偏移], {0x[二级], 0x[三级], ...})
uintptr_t ptr_chain(HANDLE h, uintptr_t a, const uint32_t *offs, int n) {
    for (int i = 0; i < n; i++) {
        uintptr_t v = rpm64(h, a);
        if (!v) return 0;
        a = v + offs[i];
    }
    return a;
}
