## 第一步：进程与模块基址（用户态验证，先跑起来）

```cpp
// base.cpp — 编译: cl /std:c++17 base.cpp
#include <windows.h>
#include <TlHelp32.h>
#include <cstdio>
#include <cstring>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    CloseHandle(snap);
    return 0;
}

static ULONG_PTR ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, mod)) { CloseHandle(snap); return (ULONG_PTR)me.modBaseAddr; }
    CloseHandle(snap);
    return 0;
}

int wmain() {
    const wchar_t* proc = L"[进程名].exe";   // ← 填目标进程名
    const wchar_t* mod  = L"[模块名].exe";   // ← 填主模块名

    DWORD pid = FindPid(proc);
    if (!pid) { printf("[!] pid not found: %ls\n", proc); return 1; }
    ULONG_PTR base = ModuleBase(pid, mod);
    printf("[+] pid=0x%lX  base=0x%p\n", pid, (void*)base);

    // 拿读写句柄（如果被 ObRegisterCallbacks 拦，这步会失败，转内核驱动）
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("[!] OpenProcess failed: %lu (需要内核驱动读写)\n", GetLastError()); return 1; }
    printf("[+] handle ok\n");

    // 示例：读模块基址处的前 16 字节，确认可读
    unsigned char buf[16]{};
    SIZE_T got = 0;
    if (ReadProcessMemory(h, (LPCVOID)base, buf, sizeof(buf), &got))
        for (int i = 0; i < 16; ++i) printf("%02X ", buf[i]);
    printf("\n");
    CloseHandle(h);
    return 0;
}
```

